//! Writes the function reference for `datafusion-spark` as Markdown.
//!
//! The content comes from each function's `documentation()`, which is generated by the
//! `#[user_doc]` attribute. Usage:
//!
//! ```text
//! cargo run -p datafusion-spark-docgen --bin print_functions_docs -- <output-dir>
//! ```
//!
//! The output directory gets a `README.md` index and one page per function type and doc
//! section, for example `scalar/math.md`. Called from `dev/update_function_docs.sh`, which
//! writes to `docs/functions`. Functions that don't implement `documentation()` yet are listed
//! on stderr.

use datafusion_expr::{
    DocSection, Documentation, aggregate_doc_sections, scalar_doc_sections,
    window_doc_sections,
};
use std::collections::HashMap;
use std::fmt::Write as _;
use std::path::Path;

const LICENSE_HEADER: &str = "<!--
SPDX-License-Identifier: Apache-2.0
SPDX-FileCopyrightText: See the NOTICE file distributed with this work for additional information regarding copyright ownership
SPDX-FileContributor: Licensed to the Apache Software Foundation (ASF) under one or more contributor license agreements
-->

<!---
This file was generated by the dev/update_function_docs.sh script.
Do not edit it manually as changes will be overwritten.
Instead, edit the #[user_doc] attributes on the functions and run the script.
-->
";

/// Name, aliases and documentation of a scalar, aggregate or window function.
struct FunctionDoc {
    name: String,
    aliases: Vec<String>,
    documentation: Option<Documentation>,
}

/// Collects [`FunctionDoc`]s from a list of `ScalarUDF`s, `AggregateUDF`s or `WindowUDF`s,
/// which share these methods but no common trait.
macro_rules! function_docs {
    ($udfs:expr) => {
        $udfs
            .iter()
            .map(|f| FunctionDoc {
                name: f.name().to_string(),
                aliases: f.aliases().to_vec(),
                documentation: f.documentation().cloned(),
            })
            .collect::<Vec<_>>()
    };
}

/// One generated page: the functions of one type (scalar, aggregate or window) in one doc
/// section.
struct Page<'a> {
    /// Path relative to the output directory, for example `scalar/math.md`
    path: String,
    type_title: &'static str,
    section: &'a DocSection,
    functions: Vec<&'a FunctionDoc>,
}

impl Page<'_> {
    /// Function names and aliases, sorted, so that aliases can be looked up too
    fn names(&self) -> Vec<(&str, &FunctionDoc)> {
        let mut names: Vec<(&str, &FunctionDoc)> = self
            .functions
            .iter()
            .flat_map(|f| {
                std::iter::once(f.name.as_str())
                    .chain(f.aliases.iter().map(String::as_str))
                    .map(move |n| (n, *f))
            })
            .collect();
        names.sort_by_key(|(n, _)| *n);
        names
    }
}

fn main() {
    let Some(out_dir) = std::env::args().nth(1) else {
        eprintln!("usage: print_functions_docs <output-dir>");
        std::process::exit(2);
    };
    let out_dir = Path::new(&out_dir);

    let scalar: Vec<FunctionDoc> =
        function_docs!(datafusion_spark::all_default_scalar_functions());
    let aggregate: Vec<FunctionDoc> =
        function_docs!(datafusion_spark::all_default_aggregate_functions());
    let window: Vec<FunctionDoc> =
        function_docs!(datafusion_spark::all_default_window_functions());

    let mut pages = Vec::new();
    let mut undocumented = Vec::new();
    for (title, dir, functions, known_sections) in [
        (
            "Scalar Functions",
            "scalar",
            &scalar,
            scalar_doc_sections::doc_sections(),
        ),
        (
            "Aggregate Functions",
            "aggregate",
            &aggregate,
            aggregate_doc_sections::doc_sections(),
        ),
        (
            "Window Functions",
            "window",
            &window,
            window_doc_sections::doc_sections(),
        ),
    ] {
        pages.extend(pages_for_type(title, dir, functions, &known_sections));
        undocumented.extend(
            functions
                .iter()
                .filter(|f| f.documentation.is_none())
                .map(|f| format!("{} ({})", f.name, title.to_lowercase())),
        );
    }

    // Page of every function name and alias, so links can cross pages
    let page_of: HashMap<&str, &str> = pages
        .iter()
        .flat_map(|p| p.names().into_iter().map(|(n, _)| (n, p.path.as_str())))
        .collect();

    write_file(&out_dir.join("README.md"), &index_page(&pages));
    for page in &pages {
        write_file(&out_dir.join(&page.path), &section_page(page, &page_of));
    }

    if !undocumented.is_empty() {
        undocumented.sort();
        eprintln!(
            "INFO: {} functions do not implement `documentation()` yet:",
            undocumented.len()
        );
        for name in undocumented {
            eprintln!("  - {name}");
        }
    }
}

fn write_file(path: &Path, contents: &str) {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)
            .unwrap_or_else(|e| panic!("creating {}: {e}", parent.display()));
    }
    std::fs::write(path, contents)
        .unwrap_or_else(|e| panic!("writing {}: {e}", path.display()));
}

/// File name for a doc section, for example "Time and Date Functions" -> `time_and_date.md`.
fn section_file_name(label: &str) -> String {
    let label = label.strip_suffix(" Functions").unwrap_or(label);
    let slug: String = label
        .to_lowercase()
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c } else { '_' })
        .collect();
    format!("{slug}.md")
}

/// Builds one page per doc section of a function type (scalar, aggregate or window).
///
/// Sections follow DataFusion's order. Sections that DataFusion doesn't define (for example
/// "URL Functions") come after it, sorted by label.
fn pages_for_type<'a>(
    type_title: &'static str,
    dir: &str,
    functions: &'a [FunctionDoc],
    known_sections: &[DocSection],
) -> Vec<Page<'a>> {
    let mut sections: Vec<&DocSection> = Vec::new();
    for section in functions
        .iter()
        .filter_map(|f| f.documentation.as_ref())
        .map(|d| &d.doc_section)
        .filter(|s| s.include)
    {
        if !sections.iter().any(|s| s.label == section.label) {
            sections.push(section);
        }
    }
    let rank = |s: &DocSection| {
        known_sections
            .iter()
            .position(|k| k.label == s.label)
            .unwrap_or(known_sections.len())
    };
    sections.sort_by(|a, b| rank(a).cmp(&rank(b)).then(a.label.cmp(b.label)));

    sections
        .into_iter()
        .map(|section| Page {
            path: format!("{dir}/{}", section_file_name(section.label)),
            type_title,
            section,
            functions: functions
                .iter()
                .filter(|f| {
                    f.documentation
                        .as_ref()
                        .is_some_and(|d| d.doc_section.label == section.label)
                })
                .collect(),
        })
        .collect()
}

/// The `README.md` index: each section page with its function count, then every function
/// name in alphabetical order.
fn index_page(pages: &[Page]) -> String {
    let mut docs = String::from(LICENSE_HEADER);
    let _ = writeln!(
        docs,
        "\n# datafusion-spark Function Reference\n\n\
         Functions in this crate emulate Apache Spark's behavior. Each entry describes how the\n\
         function differs from the DataFusion built-in of the same name, if there is one."
    );

    let mut current_type = "";
    for page in pages {
        if page.type_title != current_type {
            current_type = page.type_title;
            let _ = writeln!(docs, "\n## {current_type}\n");
        }
        let _ = writeln!(
            docs,
            "- [{}]({}) ({})",
            page.section.label,
            page.path,
            page.functions.len()
        );
    }

    let mut all: Vec<(&str, &Page)> = pages
        .iter()
        .flat_map(|p| p.names().into_iter().map(move |(n, _)| (n, p)))
        .collect();
    all.sort_by_key(|(n, p)| (*n, p.path.as_str()));
    let _ = writeln!(docs, "\n## All Functions\n");
    for (name, page) in all {
        let _ = writeln!(docs, "- [{name}]({}#{name})", page.path);
    }
    docs
}

/// A section page, for example the scalar math functions.
fn section_page(page: &Page, page_of: &HashMap<&str, &str>) -> String {
    let mut docs = String::from(LICENSE_HEADER);
    let section = page.section;
    let _ = writeln!(
        docs,
        "\n# {} ({})\n\nPart of the [datafusion-spark function reference](../README.md).\n",
        section.label,
        page.type_title.to_lowercase()
    );
    if let Some(description) = section.description {
        let _ = writeln!(docs, "{description}\n");
    }

    let names = page.names();
    for (name, _) in &names {
        let _ = writeln!(docs, "- [{name}](#{name})");
    }

    for (name, f) in names {
        if name != f.name {
            let _ = writeln!(docs, "\n## `{name}`\n");
            let _ = writeln!(docs, "_Alias of [{0}](#{0})._", f.name);
            continue;
        }
        let Some(d) = &f.documentation else {
            unreachable!("only documented functions are in a section")
        };

        let _ = writeln!(docs, "\n## `{name}`\n");
        let _ = writeln!(docs, "{}\n", d.description);
        let _ = writeln!(docs, "```sql\n{}\n```", d.syntax_example);

        if let Some(args) = &d.arguments {
            let _ = writeln!(docs, "\n### Arguments\n");
            for (arg_name, arg_desc) in args {
                let _ = writeln!(docs, "- **{arg_name}**: {arg_desc}");
            }
        }

        if let Some(example) = &d.sql_example {
            let _ = writeln!(docs, "\n### Example\n\n{example}");
        }

        if let Some(alt_syntax) = &d.alternative_syntax {
            let _ = writeln!(docs, "\n### Alternative Syntax\n");
            for syntax in alt_syntax {
                let _ = writeln!(docs, "```sql\n{syntax}\n```");
            }
        }

        if !f.aliases.is_empty() {
            let _ = writeln!(docs, "\n### Aliases\n");
            for alias in &f.aliases {
                let _ = writeln!(docs, "- {}", alias.replace('_', r"\_"));
            }
        }

        if let Some(related) = &d.related_udfs {
            let _ = writeln!(docs, "\n**Related functions**:\n");
            for r in related {
                match page_of.get(r.as_str()) {
                    Some(path) if *path == page.path => {
                        let _ = writeln!(docs, "- [{r}](#{r})");
                    }
                    Some(path) => {
                        let _ = writeln!(docs, "- [{r}](../{path}#{r})");
                    }
                    // Not a datafusion-spark function, so there is no page to link to
                    None => {
                        let _ = writeln!(docs, "- {r}");
                    }
                }
            }
        }
    }
    docs
}
